#!/bin/bash
# run_testlist_suite.sh — run every corpus_suite_*.json (generated by
# rl-coverage/level11_maxconfig/gen_testlist_corpora.py) through the already-built
# opentitan-upstream Vtop, one coverage_suite_<name>.dat per test. Continues past a
# per-test failure instead of aborting the whole suite (unlike run_constrained_random.sh,
# which is single-corpus and can afford `set -e`).
#
# Resumable: a test whose coverage_suite_<name>.dat already exists (from a prior run
# that was interrupted, e.g. Ctrl+C / kill / TaskStop) is skipped, not re-run — so
# stopping partway through and re-invoking this script picks up where it left off
# instead of redoing already-finished tests. Pass --force to ignore existing .dat
# files and re-run everything (e.g. after regenerating corpora with new seeds).
#
# Usage:
#   ./run_testlist_suite.sh [--force]
#
# Then: python3 ../rl-coverage/level11_maxconfig/aggregate_suite_coverage.py
#       (safe to run at any time, including mid-suite — it unions whatever
#       coverage_suite_*.dat files exist so far)
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "${IBEX_VENV:-$HOME/ibex_env}/bin/activate"
cd "$SCRIPT_DIR"

# Vtop is invoked directly below (not via `make`), so it doesn't automatically
# inherit the LD_LIBRARY_PATH cocotb's Makefiles set up for the linker to find
# libpythonX.Y.so — matters especially when the venv's underlying interpreter
# is an Anaconda install, whose lib dir isn't on the system's default linker
# search path. cocotb-config reports the exact libpython path cocotb itself
# was built against, so reuse that instead of guessing.
if command -v cocotb-config >/dev/null 2>&1; then
    export LD_LIBRARY_PATH="$(dirname "$(cocotb-config --libpython)"):${LD_LIBRARY_PATH:-}"
fi

FORCE=0
[ "$1" = "--force" ] && FORCE=1

CORPUS_DIR="$SCRIPT_DIR/../rl-coverage/level11_maxconfig"
SIM_BUILD=./sim_build_opentitan_upstream

if [ ! -x "$SIM_BUILD/Vtop" ]; then
    echo "ERROR: $SIM_BUILD/Vtop not found — build it first with:"
    echo "  make -f Makefile.upstream_opentitan"
    exit 1
fi

shopt -s nullglob
CORPORA=("$CORPUS_DIR"/corpus_suite_*.json)
if [ ${#CORPORA[@]} -eq 0 ]; then
    echo "ERROR: no corpus_suite_*.json found in $CORPUS_DIR — run gen_testlist_corpora.py first"
    exit 1
fi

N_OK=0
N_FAIL=0
N_SKIP=0
FAILED_NAMES=()

for corpus in "${CORPORA[@]}"; do
    name=$(basename "$corpus" .json)
    name=${name#corpus_suite_}
    dat="coverage_suite_${name}.dat"
    trace="trace_core_00000000_suite_${name}.log"

    if [ "$FORCE" -eq 0 ] && [ -s "$dat" ]; then
        echo "=== $name === SKIP (already done, .dat exists — use --force to re-run)"
        N_SKIP=$((N_SKIP + 1))
        continue
    fi

    echo "=== $name ==="
    rm -f "$dat"
    if MODULE=test_run_for_l8 RL_L8_JSON="$corpus" \
        "$SIM_BUILD/Vtop" "+verilator+coverage+file+${dat}"; then
        cp trace_core_00000000.log "$trace" 2>/dev/null || true
        if [ -f "$dat" ]; then
            N_OK=$((N_OK + 1))
        else
            echo "  WARNING: run reported success but $dat is missing"
            N_FAIL=$((N_FAIL + 1))
            FAILED_NAMES+=("$name")
        fi
    else
        echo "  FAILED: $name"
        N_FAIL=$((N_FAIL + 1))
        FAILED_NAMES+=("$name")
    fi
done

echo ""
echo "=== Suite run complete: $N_OK ok, $N_FAIL failed, $N_SKIP skipped-already-done (of ${#CORPORA[@]}) ==="
if [ $N_FAIL -gt 0 ]; then
    echo "Failed tests: ${FAILED_NAMES[*]}"
fi
